Translate the following GNU C++ code to Python 3 code. The code reads and writes I/O from the console. Your translated code should have the exact same functionality as the given code, meaning that it should have the same output for any given input.
Print your translated code and also the confidence score you give to your translation. The confidence score should be a number between 0 and 1. The format of the output should be:
<translated_code>
<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original GNU C++ code you have to translate:
<original_code>
#include <iostream>
#include <cmath>
using namespace std;

int main() {
    long long a, b, n;
    cin >> a >> b >> n;
    double a_d = a, b_d = b;
    double min_error = 1e9;
    double ratio = a_d / b_d;
    long long best_num = 0, best_den = 1;
    for (long long i = 1; i <= n; ++i) {
        long long num_candidate = (a * i) / b;
        double current_ratio = (double)num_candidate;
        double error1 = fabs(current_ratio / i - ratio);
        double error2 = fabs((current_ratio + 1.0) / i - ratio);
        if (error1 < min_error || (error1 == min_error && (i < best_den || (i == best_den && num_candidate < best_num)))) {
            min_error = error1;
            best_num = num_candidate;
            best_den = i;
        }
        if (error2 < min_error || (error2 == min_error && (i < best_den || (i == best_den && num_candidate + 1 < best_num)))) {
            min_error = error2;
            best_num = num_candidate + 1;
            best_den = i;
        }
        if (num_candidate > 0) {
            double error3 = fabs((num_candidate - 1.0) / i - ratio);
            if (error3 < min_error || (error3 == min_error && (i < best_den || (i == best_den && num_candidate - 1 < best_num)))) {
                min_error = error3;
                best_num = num_candidate - 1;
                best_den = i;
            }
        }
    }
    cout << best_num << "/" << best_den << endl;
    return 0;
}
